def rule(grid, connectivity=4, only_boundary_ones=True):
 H,W=grid.shape; comp=np.zeros((H,W),bool); q=deque([(0,0)]); comp[0,0]=1
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 while q:
  r,c=q.popleft()
  for dr,dc in dirs:
   rr,cc=r+dr,c+dc
   if 0<=rr<H and 0<=cc<W and grid[rr,cc]==8 and not comp[rr,cc]:comp[rr,cc]=1;q.append((rr,cc))
 # label 1 comps 4-connect, boundary labels
 lab=np.zeros((H,W),int); touches={}; k=0
 for r in range(H):
  for c in range(W):
   if grid[r,c]==1 and not lab[r,c]:
    k+=1; q=deque([(r,c)]); lab[r,c]=k; touch=False
    while q:
     y,x=q.popleft(); touch |= y==0 or y==H-1 or x==0 or x==W-1
     for dy,dx in dirs:
      yy,xx=y+dy,x+dx
      if 0<=yy<H and 0<=xx<W and grid[yy,xx]==1 and not lab[yy,xx]:lab[yy,xx]=k;q.append((yy,xx))
    touches[k]=touch
 out=grid.copy()
 for r in range(H):
  for c in range(W):
   if grid[r,c]!=8 or not comp[r,c]:continue
   hit_edge= r==0 or r==H-1 or c==0 or c==W-1
   hit_ones=False
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     rr,cc=r+dr,c+dc
     if (dr or dc) and 0<=rr<H and 0<=cc<W and grid[rr,cc]==1 and (not only_boundary_ones or touches[lab[rr,cc]]):hit_ones=True
   if hit_edge or hit_ones:out[r,c]=7
 return out
